-- Professional Arabic localization of the final PMBOK 8 / ECO 2026 item bank.
-- Stable item IDs, option IDs, answer keys, scoring metadata, and telemetry remain
-- shared with English so both language forms are psychometrically equivalent.

update public.diagnostic_items set
  stem_ar = 'يدخل فريق متعدد التخصصات تكراراً حرجاً، في حين يختلف اختصاصيان حول ملكية مهمة تكامل. وقد أدى نقاشهما إلى تأخير التخطيط، وبدأ أعضاء آخرون في الفريق بالانحياز إلى طرف أو آخر. لا يزال هدف التسليم قابلاً للتحقيق إذا تحسن التعاون سريعاً. ما أول إجراء ينبغي لمدير المشروع اتخاذه لاستعادة العمل الجماعي المنتج؟',
  options_ar = '[{"id":"A","text":"تيسير حوار بين الاختصاصيين لتحديد مصدر الخلاف، والاتفاق على معايير الملكية، واختيار حل مناسب."},{"id":"B","text":"إسناد المهمة إلى الاختصاصي ذي الأقدمية الأطول في المؤسسة."},{"id":"C","text":"تقسيم المهمة بالتساوي حتى إن تعذر فصل أعمال التكامل."},{"id":"D","text":"تصعيد أمر الاختصاصيين إلى مديريهم الوظيفيين قبل مناقشة الخلاف."}]'::jsonb,
  rationale_correct_ar = 'تؤدي معالجة مصدر الخلاف والاتفاق على حل إلى استعادة وضوح الملكية مع الحفاظ على مساءلة الفريق.',
  rationale_distractors_ar = '{"B":"لا تُعد الأقدمية دليلاً على المسؤولية الأنسب عن أعمال التكامل.","C":"قد يؤدي التقسيم الاعتباطي إلى واجهات غير واضحة وازدواجية في المساءلة.","D":"يتجاوز التصعيد المباشر خلافاً يستطيع الفريق محاولة حله تعاونياً أولاً."}'::jsonb
where eco_task = 'People-1';

update public.diagnostic_items set
  stem_ar = 'يتجاوز أحد المعنيين ذوي المناصب العليا قناة التواصل المتفق عليها بانتظام، ويكلّف أعضاء الفريق بأعمال عاجلة مباشرة. تبدو الطلبات ذات قيمة، لكنها تربك الالتزامات وتسبب غموضاً في الأولويات. يطلب الفريق من مدير المشروع إيقاف هذه المقاطعات مع الحفاظ على العلاقة. ما الاستجابة الأنسب من مدير المشروع؟',
  options_ar = '[{"id":"A","text":"رفض كل طلب ذي صلة لم يرد عبر القناة المتفق عليها."},{"id":"B","text":"الاجتماع بالمعني، وتوضيح القيمة ودرجة الاستعجال، والاتفاق على كيفية تقييم الطلبات المستقبلية وترتيب أولوياتها."},{"id":"C","text":"توجيه أعضاء الفريق إلى تجاهل المعني من دون مناقشة إضافية."},{"id":"D","text":"قبول العمل العاجل وتعديل التزامات التكرار بعد إنجازه."}]'::jsonb,
  rationale_correct_ar = 'يحافظ التواصل المباشر على العلاقة، ويعيد في الوقت نفسه ترتيب الأولويات بشفافية وتركيز الفريق.',
  rationale_distractors_ar = '{"A":"قد يؤدي الرفض التلقائي إلى إهدار قيمة والإضرار بالمشاركة.","C":"يترك التجنب توقعات المعني ومشكلة الحوكمة بلا حل.","D":"يؤدي قبول المقاطعة إلى تطبيع تجاوز عملية ترتيب الأولويات المتفق عليها."}'::jsonb
where eco_task = 'People-2';

update public.diagnostic_items set
  stem_ar = 'أثناء التنفيذ، بدأ عضو كفء في الفريق بإخفاق التزاماته بعد تكليفه بتقنية غير مألوفة. يتجنب الشخص الحديث عن الصعوبة، وبدأ زملاؤه بهدوء إكمال العمل غير المنجز. يتراجع أداء التسليم، مع بقاء وقت يسمح بالتعافي من دون تغيير النطاق. ما أول إجراء ينبغي لمدير المشروع اتخاذه؟',
  options_ar = '[{"id":"A","text":"إعادة إسناد العمل غير المألوف وتقليص مسؤوليات الشخص بصفة دائمة."},{"id":"B","text":"انتظار الشخص حتى يطلب المساعدة لأن إثارة مخاوف الأداء قد تقلل الثقة."},{"id":"C","text":"إجراء محادثة خاصة، وتحديد فجوة القدرة، والاتفاق على دعم بالتوجيه أو العمل الثنائي مع نقاط متابعة."},{"id":"D","text":"تقدير الزملاء الذين يكملون العمل غير المنجز والإبقاء على هذا الترتيب."}]'::jsonb,
  rationale_correct_ar = 'يعالج التشخيص الخاص والتطوير المدعوم الأداء والسلامة النفسية من دون إخفاء الفجوة.',
  rationale_distractors_ar = '{"A":"تتجنب إعادة الإسناد الدائمة التطوير وقد تهدر القدرة المتاحة.","B":"يسمح الانتظار بتفاقم مخاطر التسليم والرفاه.","D":"يخفي الحل الالتفافي السبب ويحمّل أعضاء الفريق الآخرين عبئاً زائداً."}'::jsonb
where eco_task = 'People-3';

update public.diagnostic_items set
  stem_ar = 'يضم فريق افتراضي حديث التشكيل أعضاء من ثقافات ومناطق زمنية متعددة. يهيمن مشاركان متمرسان على الاجتماعات، بينما نادراً ما يساهم الآخرون حتى عندما تكون خبراتهم ذات صلة. تجري إعادة النظر في قرارات مبكرة لأن وجهات نظر مهمة لم تُطرح. ما الإجراء الأنسب الذي ينبغي لمدير المشروع اتخاذه تالياً؟',
  options_ar = '[{"id":"A","text":"مطالبة كل مشارك ذي صلة بالتحدث للمدة الزمنية نفسها."},{"id":"B","text":"الطلب من العضوين المتمرسين اعتماد القرارات بعد كل اجتماع."},{"id":"C","text":"تحويل القرارات ذات الصلة إلى تصويت غير متزامن من دون مناقشة."},{"id":"D","text":"استخدام تيسير شامل، وقنوات مشاركة متنوعة، ودعوات صريحة للاستفادة من الخبرات ذات الصلة."}]'::jsonb,
  rationale_correct_ar = 'تُظهر آليات المشاركة الشاملة والمتعددة وجهات النظر ذات الصلة من دون فرض مساواة مصطنعة.',
  rationale_distractors_ar = '{"A":"لا يضمن تساوي وقت الحديث مساهمة ذات صلة أو آمنة نفسياً.","B":"يؤدي تركيز سلطة الاعتماد إلى تعزيز عدم التوازن.","C":"يلغي التصويت وحده بناء السياق وقد يُبقي الآخرين صامتين."}'::jsonb
where eco_task = 'People-4';

update public.diagnostic_items set
  stem_ar = 'يختلف مالك المنتج والقائد التقني حول إصدار ميزة تتضمن قيداً معروفاً. يدعم كل موقف أدلة معقولة، لكن النقاش أصبح شخصياً ويؤثر في الفريق. يلزم اتخاذ قرار قريباً لحماية قيمة العميل. ما أول إجراء ينبغي لمدير المشروع اتخاذه؟',
  options_ar = '[{"id":"A","text":"إعادة صياغة الخلاف حول نتائج الإصدار المشتركة، والأدلة، وتحمّل المخاطر، وسلطة القرار المتفق عليها."},{"id":"B","text":"دعم مالك المنتج لأن قيمة العميل تتغلب عادة على الاعتبارات التقنية."},{"id":"C","text":"دعم القائد التقني لأن مخاوف الجودة تمنع الإصدار عادة."},{"id":"D","text":"تأجيل القرار إلى أن يختفي الخلاف الشخصي من تلقاء نفسه."}]'::jsonb,
  rationale_correct_ar = 'تفصل المعايير المشتركة وسلطة القرار الخلاف العلاقي عن قرار الإصدار القائم على الأدلة.',
  rationale_distractors_ar = '{"B":"لا يتغلب دور واحد تلقائياً على أدلة تقنية مشروعة.","C":"يجب تقييم المخاوف التقنية مقابل القيمة والمخاطر، لا التعامل معها بوصفها حكماً مطلقاً.","D":"لا يدير التأجيل الخلاف ولا يحمي نافذة اتخاذ القرار."}'::jsonb
where eco_task = 'People-5';

update public.diagnostic_items set
  stem_ar = 'في منتصف المشروع، استبدل الراعي مديراً وظيفياً رئيسياً كان يوفر عدة موارد حرجة. يشكك المدير الجديد في منافع المشروع ولم يؤكد استمرار توافر الموارد. يمكن مواصلة العمل لفترة وجيزة، لكن الأنشطة المقبلة تعتمد على أولئك الاختصاصيين. ما الإجراء التالي الذي ينبغي لمدير المشروع اتخاذه؟',
  options_ar = '[{"id":"A","text":"مواصلة العمل إلى أن تُسحب الموارد لأن الخطة لا تزال معتمدة."},{"id":"B","text":"إشراك المدير الجديد، وإعادة تأكيد المنافع والأولويات، والتفاوض على التزامات الموارد المطلوبة."},{"id":"C","text":"استبدال الاختصاصيين بمتعاقدين خارجيين قبل استكمال تحليل الأثر."},{"id":"D","text":"طلب تدخل الراعي لإلزام المدير قبل فهم مخاوفه."}]'::jsonb,
  rationale_correct_ar = 'يوائم الإشراك المبكر التوقعات ويختبر افتراضات الموارد قبل التصعيد أو الاستبدال.',
  rationale_distractors_ar = '{"A":"لا تلغي الخطة المعتمدة خطراً جديداً ومادياً متعلقاً بالموارد.","C":"يُعد الاستبدال سابقاً لأوانه قبل فهم التوافر والبدائل.","D":"قد يرسخ التصعيد المبكر المقاومة ويفتقر إلى أساس مستنير."}'::jsonb
where eco_task = 'People-6';

update public.diagnostic_items set
  stem_ar = 'ينجز فريق عالي الأداء العمل المخطط باستمرار، لكن أعضاءه يعتمدون على مدير المشروع في قرارات روتينية تقع ضمن خبراتهم. بدأ هذا الاعتماد يبطئ الاستجابة للقضايا الناشئة. يريد الراعي الحفاظ على سرعة التسليم مع ازدياد التعقيد. ما الإجراء الأنسب لمدير المشروع؟',
  options_ar = '[{"id":"A","text":"مواصلة اتخاذ القرارات الروتينية ليحافظ الفريق على سجل التسليم."},{"id":"B","text":"اشتراط موافقة الراعي على القرارات ذات الصلة مع ازدياد التعقيد."},{"id":"C","text":"توضيح حدود القرار، وتفويض السلطة المناسبة، وتوجيه الفريق أثناء تحمله الملكية."},{"id":"D","text":"تدوير دور مدير المشروع بين أعضاء الفريق في كل تكرار."}]'::jsonb,
  rationale_correct_ar = 'تبني السلطة المفوضة بوضوح الاستقلالية، مع الإبقاء على الحوكمة للقرارات الواقعة خارج حدود الفريق.',
  rationale_distractors_ar = '{"A":"الاعتماد المركزي هو القيد المحدد وسيتفاقم مع التعقيد.","B":"تزيد المركزية الإضافية بطء القرارات.","D":"لا يتناسب تدوير الدور مع المشكلة ولا يحدد السلطة."}'::jsonb
where eco_task = 'People-7';

update public.diagnostic_items set
  stem_ar = 'بدأ صاحب مصلحة كان داعماً قوياً للمشروع بمقاومته بعد أن علم أن سير عمل جديداً سيغير المسؤوليات في إدارته. يتمتع المعني بنفوذ لدى عدة مستخدمين وقد يقلل التبني. لا يزال موعد التنفيذ بعد عدة أشهر. ما أول إجراء ينبغي لمدير المشروع اتخاذه؟',
  options_ar = '[{"id":"A","text":"تقليل وصول المعني إلى معلومات المشروع حتى التنفيذ."},{"id":"B","text":"الطلب من الراعي توجيه المعني إلى دعم سير العمل المعتمد."},{"id":"C","text":"مواصلة خطة الإشراك لأن المعني كان داعماً سابقاً."},{"id":"D","text":"الاجتماع بالمعني لفهم الأثر، ومعالجة المخاوف، وإشراك المستخدمين المتأثرين في نهج الانتقال."}]'::jsonb,
  rationale_correct_ar = 'يدعم فهم الأثر وإشراك المتأثرين المواءمة والثقة والتبني قبل انتشار المقاومة.',
  rationale_distractors_ar = '{"A":"يزيد حجب المعلومات عدم التيقن وانعدام الثقة.","B":"قد تفرض السلطة الامتثال لكنها لا تبني التبني.","C":"تتطلب أوضاع المعني المتغيرة تفصيل خطة الإشراك."}'::jsonb
where eco_task = 'People-8';

update public.diagnostic_items set
  stem_ar = 'خلال التخطيط، يحدد الفريق تبعية تنظيمية قد تؤخر معلماً رئيسياً. لم تؤكد الجهة التنظيمية مدة المراجعة، وتُظهر المشاريع السابقة تفاوتاً كبيراً في أوقات الاعتماد. يظل تاريخ الإكمال التعاقدي ثابتاً. ما أول إجراء ينبغي لمدير المشروع اتخاذه لمعالجة عدم التيقن؟',
  options_ar = '[{"id":"A","text":"نمذجة عدم التيقن في مدة الاعتماد، والتواصل المبكر مع الجهة التنظيمية، وإدراج خيارات الاستجابة في الخطة المتكاملة."},{"id":"B","text":"استخدام أقصر مدة اعتماد تاريخية لحماية التاريخ التعاقدي."},{"id":"C","text":"حذف المراجعة التنظيمية من الجدول لأن مدتها خاضعة لطرف خارجي."},{"id":"D","text":"إضافة أطول مدة تاريخية بوصفها احتياطياً ثابتاً من دون تحليل إضافي."}]'::jsonb,
  rationale_correct_ar = 'ينشئ تحليل عدم التيقن المتكامل والتواصل المبكر خيارات واقعية مع الحفاظ على الامتثال.',
  rationale_distractors_ar = '{"B":"يخفي اختيار المدة المتفائلة تعرضاً جوهرياً في الجدول.","C":"يظل العمل الخارجي قيداً على المشروع ويجب تمثيله.","D":"قد يشوه افتراض واحد لأسوأ حالة الخطة من دون تقييم الاحتمالات أو الاستجابات."}'::jsonb
where eco_task = 'Process-1';

update public.diagnostic_items set
  stem_ar = 'استوفت زيادة في المنتج معايير القبول التقنية وسُلّمت في الموعد. لا تُظهر تحليلات الاستخدام أي تغير في سلوك العميل المحدد في دراسة الجدوى، ومع ذلك يصف الفريق الزيادة بأنها حققت القيمة كاملة. ما الدليل المفقود الذي يمنع مدير المشروع بصورة مباشرة من التحقق من تحقق القيمة؟',
  options_ar = '[{"id":"A","text":"مقارنة التغير الفعلي في نتائج العميل بمقياس المنفعة المحدد للزيادة."},{"id":"B","text":"تأكيد موقّع بأن فعاليات التكرار عُقدت في مواعيدها المخططة."},{"id":"C","text":"تفسير للتباين يبيّن أن جهد التطوير بقي ضمن تقدير الفريق."},{"id":"D","text":"تحديث لسجل المعنيين يوثق من حضر عرض الزيادة."}]'::jsonb,
  rationale_correct_ar = 'يتطلب التحقق من القيمة دليلاً مقابل المنفعة أو نتيجة العميل المستهدفة، لا مجرد نشاط التسليم أو الإكمال التقني.',
  rationale_distractors_ar = '{"B":"إكمال الفعاليات دليل على العملية وليس على المنفعة.","C":"لا يثبت تباين الجهد قيمة للعميل أو للأعمال.","D":"لا تقيس سجلات الحضور ما إذا كانت النتيجة المتوقعة قد تغيرت."}'::jsonb
where eco_task = 'Process-2';

update public.diagnostic_items set
  stem_ar = 'أبلغ مورّد بأن مكوّناً مخصصاً سيتأخر ثلاثة أسابيع. تعتمد عليه عدة أنشطة لاحقة، لكن قد يستطيع الفريق إعادة تسلسل بعض الأعمال. لم يقدم المورّد بعد خطة تعافٍ. ما أول إجراء ينبغي لمدير المشروع اتخاذه قبل التوصية بتغيير الجدول؟',
  options_ar = '[{"id":"A","text":"تحريك المعلم التعاقدي ثلاثة أسابيع فوراً."},{"id":"B","text":"إنهاء التعاقد مع المورّد قبل طلب معلومات التعافي."},{"id":"C","text":"الحصول على خطة التعافي وتحليل آثار التبعيات وإعادة التسلسل والتكلفة والمخاطر قبل التوصية بإجراء."},{"id":"D","text":"توجيه الفرق اللاحقة إلى زيادة العمل الإضافي حتى وصول المكوّن."}]'::jsonb,
  rationale_correct_ar = 'تلزم خطة تعافٍ موثقة وتحليل متكامل للأثر قبل اختيار استجابة للجدول.',
  rationale_distractors_ar = '{"A":"قد لا يؤدي تأخر المورّد مباشرة إلى تأخر المعلم بالمدة نفسها.","B":"الإنهاء سابق لأوانه وقد يزيد القيد سوءاً.","D":"لا يعالج العمل الإضافي الأعمال المتوقفة بسبب غياب المكوّن."}'::jsonb
where eco_task = 'Process-3';

update public.diagnostic_items set
  stem_ar = 'يستخدم مشروع تطويراً تكرارياً ضمن إطار حوكمة ثابت. سرعة الفريق مستقرة، لكن اجتماعات الاعتماد الإلزامية تؤخر الزيادات المكتملة كثيراً. يريد المديرون دليلاً على استمرار الحوكمة مع تحسين التدفق. ما الإجراء الأنسب الذي ينبغي لمدير المشروع اتخاذه تالياً؟',
  options_ar = '[{"id":"A","text":"إلغاء اجتماعات الاعتماد لأن استقرار السرعة يثبت عدم الحاجة إلى الحوكمة."},{"id":"B","text":"زيادة طول التكرار لتقليل تكرار الاعتمادات."},{"id":"C","text":"إحالة كل زيادة ذات صلة مباشرة إلى الإدارة العليا."},{"id":"D","text":"تحديد احتياجات الاعتماد وحدوده، ثم تكييف الأدلة وتوقيت المراجعة للحفاظ على الرقابة مع تسريع التدفق."}]'::jsonb,
  rationale_correct_ar = 'يحافظ تفصيل الحوكمة وفق المخاطر والأدلة على المساءلة مع إزالة التأخير الممكن تجنبه.',
  rationale_distractors_ar = '{"A":"لا تلغي السرعة التزامات الحوكمة.","B":"قد تؤخر التكرارات الأطول القيمة والتغذية الراجعة من دون إصلاح تدفق الاعتماد.","C":"يزيد التصعيد الشامل التأخير ويضعف الحوكمة المفوضة."}'::jsonb
where eco_task = 'Process-4';

update public.diagnostic_items set stem_ar='أثناء الاختبار، يكتشف الفريق عيباً متكرراً سببه تفاوت تفسير أحد المتطلبات. يمكن تصحيح كل حالة منفردة، لكن قد تستمر عيوب مماثلة في الظهور. لم يتبق للإصدار سوى احتياطي محدود. ما أول إجراء ينبغي لمدير المشروع اتخاذه لحماية الجودة والتسليم؟', options_ar='[{"id":"A","text":"إجراء تحليل للسبب الجذري مع المعنيين ذوي الصلة، وتوضيح المتطلب، وتحديث ضوابط الجودة لمنع التكرار."},{"id":"B","text":"إصلاح العيوب المكتشفة فقط للحفاظ على الاحتياطي."},{"id":"C","text":"خفض حد قبول العيوب بسبب اختلاف التفسيرات."},{"id":"D","text":"تأجيل توضيح المتطلب إلى الاجتماع الاستعادي للإصدار."}]'::jsonb, rationale_correct_ar='تحمي معالجة السبب المشترك وضوابط المنع الجودة الحالية والاحتياطي المتبقي.', rationale_distractors_ar='{"B":"يُبقي إصلاح الحالات المنفردة المصدر المنهجي للعيب قائماً.","C":"لا يعالج تغيير مستوى التحمل غموض المتطلب.","D":"يسمح التأجيل بظهور عيوب إضافية يمكن تجنبها."}'::jsonb where eco_task='Process-5';

update public.diagnostic_items set stem_ar='ينفذ فريق رشيق تجربة تسعير قابلة للعكس ضمن حد رقابي معتمد: إيقاف الاختبار إذا تجاوز حجم الشكاوى 3% ليومين متتاليين. بلغت النسبة 4% في اليومين، بينما تبدو الإيرادات المبكرة إيجابية. يريد مالك المنتج جمع بيانات لأسبوع إضافي. ما الاستجابة المناسبة؟', options_ar='[{"id":"A","text":"مواصلة التجربة أسبوعاً لأن الإيرادات المبكرة قد تفوق دلالة الشكاوى."},{"id":"B","text":"إيقاف التجربة وفق الحد الرقابي المعتمد والاحتفاظ بالأدلة لقرار المنتج التالي."},{"id":"C","text":"توسيع التجربة لزيادة القوة الإحصائية لنتيجة الإيرادات."},{"id":"D","text":"انتظار قرار الراعي رغم اعتماد سلطة الإيقاف وحدّه مسبقاً."}]'::jsonb, rationale_correct_ar='ينبغي احترام شرط الإيقاف الصريح والمعتمد مسبقاً؛ ويستمر التعلم من خلال الأدلة المحفوظة والقرار اللاحق.', rationale_distractors_ar='{"A":"لا تلغي الإيرادات الإيجابية حد حماية العميل المعتمد.","C":"يزيد التوسع التعرض بعد تحقق شرط الإيقاف.","D":"يوفر الحد الرقابي المتفق عليه سلطة القرار بالفعل."}'::jsonb where eco_task='Process-6';

update public.diagnostic_items set stem_ar='قد ينشئ طلب تغيير قيمة كبيرة للأعمال، لكنه سيؤثر أيضاً في التكلفة والجدول وعقدين خارجيين. يدعم الراعي الفكرة بقوة ويطلب بدء العمل فوراً. يخضع المشروع لضبط رسمي للتغييرات. ما أول إجراء ينبغي لمدير المشروع اتخاذه؟', options_ar='[{"id":"A","text":"بدء العمل لأن دعم الراعي يُعد اعتماداً."},{"id":"B","text":"مطالبة المورّدين بتحمل الآثار ذات الصلة قبل توثيق الطلب."},{"id":"C","text":"تحليل الآثار المتكاملة ورفع الطلب إلى جهة ضبط التغيير المعتمدة."},{"id":"D","text":"رفض التغيير لأنه يؤثر في الخطوط المرجعية والعقود."}]'::jsonb, rationale_correct_ar='يمكّن التحليل المتكامل الجهة المخولة من اتخاذ قرار شفاف يوازن القيمة والخطوط المرجعية والعقود.', rationale_distractors_ar='{"A":"لا يساوي تأييد الراعي بالضرورة اعتماد التغيير من الجهة المخولة.","B":"تتطلب آثار العقود تحليلاً وتفاوضاً، لا نقلاً أحادي الجانب.","D":"الأثر المحتمل سبب للتقييم وليس سبباً للرفض التلقائي للقيمة."}'::jsonb where eco_task='Process-7';

update public.diagnostic_items set stem_ar='يسلّم مشروع هجين زيادات برمجية، بينما تتبع أعمال الإنشاء جدولاً تنبؤياً. تغيرت تبعية برمجية وقد تؤثر في معلم إنشائي مقبل. يقدم كل فريق التقدم بمقاييس مختلفة. ما أول إجراء ينبغي لمدير المشروع اتخاذه لتحديد الأثر الحقيقي؟', options_ar='[{"id":"A","text":"استخدام سرعة الفريق البرمجي مقياساً وحيداً للبرنامج."},{"id":"B","text":"استخدام تباين جدول الإنشاء مقياساً وحيداً للبرنامج."},{"id":"C","text":"مطالبة كل فريق بالتقرير منفرداً ومقارنة التقارير بعد المعلم."},{"id":"D","text":"ربط التبعية المتغيرة بالخطة المتكاملة وتقييم آثارها باستخدام مقاييس مشتركة للمعالم والقيمة."}]'::jsonb, rationale_correct_ar='تترجم الرؤية المتكاملة للتبعيات مقاييس التسليم المختلفة إلى تقييم مشترك للأثر.', rationale_distractors_ar='{"A":"لا تمثل السرعة وحدها أثر التبعية الإنشائية.","B":"يغفل تباين الجدول وحده أدلة التسليم البرمجي والقيمة.","C":"يُبقي التقرير المنفصل والمتأخر فجوة المعلومات."}'::jsonb where eco_task='Process-8';

update public.diagnostic_items set stem_ar='تعرض لوحتا معلومات للمشروع أرقاماً متعارضة للإكمال والتوقعات لأن فريقي التسليم يستخدمان تواريخ قطع وتعريفات مختلفة. ستقرر الحوكمة التمويل في مراجعة الغد، ويصر قائدا الفريقين على صحة تقريريهما. السجلات الأساسية متاحة للمقارنة. ما أول إجراء ينبغي لمدير المشروع اتخاذه لتقديم حالة موثوقة للمشروع؟', options_ar='[{"id":"A","text":"مطابقة بيانات المصدر، والتحقق من تعريفات المقاييس، وعرض التباين وأثره في القرار."},{"id":"B","text":"نشر اللوحة الأكثر إيجابية لأن المعنيين يحتاجون إلى الثقة."},{"id":"C","text":"احتساب متوسط الأرقام المتعارضة من دون فحص تعريفاتها."},{"id":"D","text":"إيقاف تقارير الحالة إلى أن ينتج النظامان قيماً متطابقة."}]'::jsonb, rationale_correct_ar='تعيد المطابقة والإفصاح الشفاف عن الأثر أساساً موثوقاً لقرارات الحوكمة.', rationale_distractors_ar='{"B":"يشوه التقرير الانتقائي الحالة ويقوض الثقة.","C":"ينتج عن متوسط مقاييس غير متوافقة نتيجة بلا معنى.","D":"يحجب إيقاف التقارير معلومات الحوكمة في وقت الحاجة إليها."}'::jsonb where eco_task='Process-9';

update public.diagnostic_items set stem_ar='يرحّل فريق رشيق عملاً غير مكتمل إلى التكرار التالي مراراً بسبب طلبات دعم عاجلة تصل بصورة غير متوقعة. يقدّر العملاء الدعم، لكن نتائج المنتج المخططة تتأخر. تتوقع القيادة استمرار الخدمتين. ما الإجراء الأنسب الذي ييسره مدير المشروع تالياً؟', options_ar='[{"id":"A","text":"رفض طلبات الدعم ذات الصلة أثناء التكرارات."},{"id":"B","text":"تحليل الطلب والقدرة مع المعنيين، ثم وضع سياسة خدمة صريحة وحماية التزامات المنتج."},{"id":"C","text":"رفع أهداف السرعة من دون تغيير القدرة أو آلية استقبال العمل."},{"id":"D","text":"ترحيل العمل غير المكتمل لفترة مفتوحة لأن الدعم يخلق قيمة للعميل."}]'::jsonb, rationale_correct_ar='تجعل سياسة صريحة للقدرة والخدمة مفاضلات القيمة مرئية وتعيد الالتزامات القابلة للتحقيق.', rationale_distractors_ar='{"A":"يتجاهل الرفض الشامل قيمة خدمة مشروعة.","C":"لا يزيل الهدف الأعلى الطلب غير المخطط.","D":"يخفي الترحيل المفتوح القيد ويقوض القدرة على التنبؤ."}'::jsonb where eco_task='Process-10';

update public.diagnostic_items set stem_ar='يبدأ سريان نظام بيئي جديد قبل اكتمال المشروع. تستوفي المخرجات الحالية المتطلبات الأصلية، لكن النشر اللاحق قد ينشئ مخاطر امتثال وسمعة. يركز الراعي على الميزانية والجدول المعتمدين. ما أول إجراء ينبغي لمدير المشروع اتخاذه؟', options_ar='[{"id":"A","text":"المواصلة بلا تغيير لأن المخرجات استوفت المتطلبات عند اعتمادها."},{"id":"B","text":"تنفيذ كل تغيير امتثال محتمل قبل التحقق من انطباقه."},{"id":"C","text":"تأكيد الالتزامات، وتقييم آثار الامتثال والأعمال، وتمرير التغييرات اللازمة عبر الحوكمة."},{"id":"D","text":"نقل ملكية الامتثال بصورة رئيسية إلى الراعي."}]'::jsonb, rationale_correct_ar='يجب تحديد الالتزامات الحالية والعواقب قبل اختيار استجابة مخولة ومتناسبة.', rationale_distractors_ar='{"A":"قد يتغير التعرض للامتثال أثناء المشروع.","B":"قد تهدر التغييرات غير المتحقق منها الموارد أو تُدخل مخاطر جديدة.","D":"يبقى مدير المشروع مسؤولاً عن تنسيق تحليل الامتثال والإجراء."}'::jsonb where eco_task='Business-1';

update public.diagnostic_items set stem_ar='أصبحت عملية تشغيل جديدة جاهزة تقنياً، وتاريخ الانتقال الإلزامي ثابت. تؤدي مجموعة تجريبية العمل بدقة بعد تدريب موجّه، بينما تستمر الفرق غير التجريبية في استخدام العملية القديمة لأن مشرفيها لم يخصصوا وقتاً للتدريب. ما التدخل الذي يعالج قيد التبني المثبت على نحو أفضل؟', options_ar='[{"id":"A","text":"إلزام المشرفين بجدولة تدريب موجّه والتحقق من الكفاءة قبل انتقال فرقهم."},{"id":"B","text":"نشر إعلان عام آخر يوضح تاريخ الانتقال الإلزامي."},{"id":"C","text":"تمديد المشروع التقني إلى أن يبلغ التبني الطوعي المستوى المتوقع."},{"id":"D","text":"استبدال العملية لأن الفرق غير التجريبية لم تتبنها تلقائياً."}]'::jsonb, rationale_correct_ar='تعزل التجربة إتاحة التدريب بوصفها قيد التبني، لذلك يعالج التدريب المملوك والتحقق من الكفاءة السبب مباشرة.', rationale_distractors_ar='{"B":"الوعي ليس القيد الذي أظهرته الأدلة.","C":"لا ينشئ التمديد المفتوح ملكية لدى المشرفين أو قدرة عملية.","D":"يثبت نجاح التجربة أن العملية نفسها قابلة للتطبيق."}'::jsonb where eco_task='Business-2';

update public.diagnostic_items set stem_ar='أبلغ مدير وظيفي مدير المشروع أن اختصاصياً لن يكون متاحاً أثناء مراجعة تصميم حرجة. افترضت خطة الموارد مشاركته الكاملة، لكن يمكن نقل المراجعة من دون التأثير في المعلم التعاقدي. يفهم اختصاصيون آخرون مؤهلون أجزاء من التصميم فقط. ما أول إجراء ينبغي لمدير المشروع اتخاذه؟', options_ar='[{"id":"A","text":"تقييم فجوة الكفاءة ومراجعة خيارات التغطية أو الجدولة الممكنة مع الفريق."},{"id":"B","text":"مطالبة الراعي بإلزام الاختصاصي بحضور المراجعة كما خُطط لها."},{"id":"C","text":"استبدال الاختصاصي بأكثر أعضاء الفريق توافراً قبل استكمال تحليل الأثر."},{"id":"D","text":"مواصلة المراجعة من دون الاختصاصي وتوثيق أي عيوب تنتج."}]'::jsonb, rationale_correct_ar='يحدد مدير المشروع فجوة القدرة أولاً ويقيّم الخيارات المتناسبة قبل التصعيد أو تغيير التكليفات.', rationale_distractors_ar='{"B":"التصعيد سابق لأوانه قبل فهم الأثر والبدائل العملية.","C":"لا يثبت التوافر وحده امتلاك الكفاءة المطلوبة.","D":"ينقل قبول فجوة معروفة خطراً يمكن تجنبه إلى عمل لاحق."}'::jsonb where eco_task='People-9';

update public.diagnostic_items set stem_ar='يختلف مهندسان متمرسان حول سبب إخفاقات التكامل المتكررة. لدى كل منهما بيانات مؤيدة، وبدأ فريقاهما بالدفاع عن حلين منفصلين. يعتمد الإصدار التالي على حل المشكلة من دون الإضرار بالتعاون. رتّب مدير المشروع جلسة عمل مشتركة. ما الطريقة الأنسب لإدارة الجلسة؟', options_ar='[{"id":"A","text":"مطالبة كل مهندس بعرض حل، ثم ترك الفريق الأكبر يصوّت."},{"id":"B","text":"تثبيت الحقائق المشتركة ومعايير القرار، ثم تقييم الفرضيتين المتنافستين معاً."},{"id":"C","text":"فصل المهندسين ومطالبة الراعي باختيار أحد الحلين المقترحين."},{"id":"D","text":"تركيز الجلسة على استعادة الانسجام وتأجيل التحليل التقني."}]'::jsonb, rationale_correct_ar='تحول الأدلة المشتركة ومعايير القرار المتفق عليها الخلاف الموقفي إلى حل تعاوني للمشكلة مع الحفاظ على الملكية.', rationale_distractors_ar='{"A":"لا يختبر تصويت الشعبية الأدلة التقنية ولا يحل أصل الخلاف.","C":"يتجاوز اختيار الراعي خبرة الفريق اللازمة لتشخيص الإخفاق.","D":"تترك معالجة العلاقة من دون تحليل تقني مشكلة التسليم بلا حل."}'::jsonb where eco_task='People-10';

update public.diagnostic_items set stem_ar='رفض ممثل العميل سير العمل الحرج نفسه مرتين لأنه لا يحقق نتيجة زمن الاستجابة المتفق عليها. معيار القبول صريح، والعيب قابل للتكرار، وستبدأ مجموعة النشر التالية غداً. يقترح قائد التسليم الإصدار ثم التصحيح لاحقاً. ما الإجراء الذي ينبغي لمدير المشروع اتخاذه؟', options_ar='[{"id":"A","text":"الإصدار للمجموعة التالية وتسجيل مخاوف العميل بوصفها طلب تحسين."},{"id":"B","text":"إيقاف النشر المتأثر، وتفعيل مسار التصحيح المتفق عليه، وإبلاغ العميل بالتزام التعافي."},{"id":"C","text":"مطالبة العميل بإعادة النظر لأن اختبارات القبول التقنية نجحت."},{"id":"D","text":"إحالة قرار القبول إلى الراعي من دون استخدام سلطة تعافي الخدمة المتفق عليها."}]'::jsonb, rationale_correct_ar='تبرر النتيجة الصريحة غير المحققة ومسار التصحيح المفوض الاحتواء والتعافي فوراً مع إعادة ضبط التوقعات بشفافية.', rationale_distractors_ar='{"A":"لا ينبغي نقل إخفاق معروف مقابل نتيجة حرجة متفق عليها إلى مستخدمين إضافيين.","C":"لا يتغلب إكمال الاختبارات التقنية على معيار نتيجة العميل.","D":"يتجاوز التصعيد سلطة متاحة بالفعل لاستجابة تعافٍ متناسبة."}'::jsonb where eco_task='People-11';

update public.diagnostic_items set stem_ar='يريد فريق مشروع استخدام مساعد ذكاء اصطناعي لتلخيص مقابلات العملاء واقتراح موضوعات لقائمة العمل. قد تسرّع الأداة الاكتشاف، لكنها قد تعالج بيانات شخصية سرية، وقد تتضمن مخرجاتها استنتاجات غير مسندة. لا توجد بعد إرشادات مؤسسية لهذا الاستخدام. ما الإجراء الأنسب الذي ييسره مدير المشروع؟', options_ar='[{"id":"A","text":"السماح بالاستخدام غير المقيد لأن إنساناً سيراجع كل بند في قائمة العمل لاحقاً."},{"id":"B","text":"حظر أدوات الذكاء الاصطناعي ذات الصلة حتى تنشر المؤسسة سياسة رسمية."},{"id":"C","text":"رفع مقابلات مجهلة الهوية قبل استكمال تحليل الأثر ومعالجة مخاوف الحوكمة بعد التجربة."},{"id":"D","text":"تقييم مخاطر البيانات والجوانب القانونية والأخلاقية والجودة، وتحديد الرقابة البشرية قبل تجربة مضبوطة."}]'::jsonb, rationale_correct_ar='يتيح التقييم المحكوم والرقابة البشرية الصريحة تجربة مسؤولة مع حماية المعنيين وجودة القرار.', rationale_distractors_ar='{"A":"لا تمنع المراجعة اللاحقة معالجة بيانات غير سليمة أو تعرضاً غير مضبوط.","B":"يهدر الحظر الشامل قيمة محتملة من دون تقييم خيار مضبوط.","C":"لا يحل إخفاء الهوية وحده مخاطر القانون والأخلاق والأمن وجودة المخرجات."}'::jsonb where eco_task='Business-4';

update public.diagnostic_items set stem_ar='يمكن لبرنامج بنية أساسية هجين استخدام مادة أقل تكلفة تستوفي الحد الأدنى للمواصفات، لكن تحليل دورة الحياة يشير إلى انبعاثات ونفقات صيانة أعلى. البديل الأكثر استدامة أعلى تكلفة أولية وقد يؤخر الشراء. نشرت المؤسسة التزامات بالاستدامة، رغم أن دراسة الجدوى لم تكممها. ما الإجراء الأنسب لمدير المشروع؟', options_ar='[{"id":"A","text":"تكميم قيمة دورة الحياة وآثار الاستدامة، ثم عرض المفاضلة عبر الحوكمة."},{"id":"B","text":"اختيار المادة الأقل تكلفة لأن المنافع المالية المعتمدة فقط تدخل دراسة الجدوى."},{"id":"C","text":"اختيار المادة المستدامة قبل تحليل الأثر لأن الالتزامات المنشورة تتغلب على قيود المشروع."},{"id":"D","text":"مطالبة المشتريات بالاختيار سراً للحفاظ على جدول التسليم."}]'::jsonb, rationale_correct_ar='يتيح تكميم آثار دورة الحياة والاستدامة قرار حوكمة قائماً على الأدلة ومتسقاً مع الاستراتيجية والقيمة.', rationale_distractors_ar='{"B":"يقلل تجاهل دورة الحياة والالتزامات الاستراتيجية المعلنة تقدير القيمة والمخاطر.","C":"الالتزامات مهمة، لكن الاختيار الأحادي غير المعتمد يتجاوز تحليل الأثر المتكامل.","D":"تقدم المشتريات الخبرة، لكنها لا تملك وحدها قرار القيمة الاستراتيجي."}'::jsonb where eco_task='Business-5';
update public.diagnostic_items set stem_ar='أثناء تخطيط النطاق، يطلب صاحب مصلحة ميزة تبدو خارج نطاق المنتج المعتمد. قد تعالج حاجة تنظيمية صحيحة، لكن الفريق لم يراجع التشريع الداعم. يطلب المعني التزاماً فورياً لتجنب التأخير. ما الإجراء التالي لمدير المشروع؟', options_ar='[{"id":"A","text":"رفض الطلب لأنه خارج خط أساس النطاق المعتمد حالياً."},{"id":"B","text":"إضافة الميزة إلى هيكل تجزئة العمل وتقديرها أثناء التنفيذ."},{"id":"C","text":"توضيح المتطلب التنظيمي وتقييم آثاره في النطاق والامتثال."},{"id":"D","text":"مطالبة الراعي باعتماد الميزة قبل أن يفحص الفريق المتطلب."}]'::jsonb, rationale_correct_ar='يجب أولاً إثبات المتطلب وآثاره قبل القبول أو الرفض أو تقديم تغيير.', rationale_distractors_ar='{"A":"قد ينشئ رفض حاجة تنظيمية غير مفحوصة تعرضاً للامتثال.","B":"تتجاوز إضافة العمل قبل التحقق والاعتماد ضبط النطاق.","D":"لا يستطيع الراعي اتخاذ قرار مستنير من دون المتطلب وتحليل الأثر."}'::jsonb where eco_task='Process-11';
update public.diagnostic_items set stem_ar='قدم متعاقد مخرجاً في الموعد، لكن الفحص كشف انحرافات طفيفة عن معايير القبول المتفق عليها. يرى المتعاقد أنها لا تؤثر في الاستخدام ويطلب القبول فوراً لبدء الفوترة. للمشروع عملية جودة ومشتريات محددة. ما الإجراء التالي لمدير المشروع؟', options_ar='[{"id":"A","text":"قبول المخرج بشروط ومطالبة المتعاقد بتصحيحه بعد الدفع."},{"id":"B","text":"توثيق عدم المطابقة واتباع عملية المراجعة والمعالجة المتفق عليها."},{"id":"C","text":"رفض العقد بأكمله لأن معايير القبول لم تتحقق بالكامل."},{"id":"D","text":"مطالبة المستخدمين بالتصويت على أهمية تصحيح الانحرافات."}]'::jsonb, rationale_correct_ar='يحمي توثيق الانحراف واستخدام عملية المعالجة الجودة والعدالة التعاقدية وقابلية القرار للتدقيق.', rationale_distractors_ar='{"A":"قد يضعف القبول المشروط النفوذ التعاقدي ويتجاوز الرقابة المتفق عليها.","C":"إنهاء العقد غير متناسب قبل تطبيق المعالجات التعاقدية.","D":"قد يفيد رأي المستخدم في فهم الأثر، لكنه لا يستبدل معايير القبول التعاقدية."}'::jsonb where eco_task='Process-12';
update public.diagnostic_items set stem_ar='يُتوقع أن ينتهي نشاط على المسار الحرج متأخراً عشرة أيام بعد تعطل معدة. حدد الفريق خيارين للتعافي: عمل إضافي بتكلفة أعلى أو إعادة تسلسل بمخاطر تقنية إضافية. تطلب الإدارة توصية قبل اجتماع الحوكمة التالي. ما الأساس الأنسب لتوصية مدير المشروع؟', options_ar='[{"id":"A","text":"اختيار العمل الإضافي لأن حماية تاريخ الإكمال المعتمد هي الأولوية الأعلى."},{"id":"B","text":"اختيار إعادة التسلسل لأنه يتجنب زيادة الميزانية المعتمدة."},{"id":"C","text":"الانتظار حتى ينتهي النشاط لأن التوقعات قد تتغير قبل اجتماع الحوكمة."},{"id":"D","text":"مقارنة الآثار والمخاطر والقيود وأولويات المعنيين الكلية للخيارين."}]'::jsonb, rationale_correct_ar='تمكّن المقارنة المتكاملة مفاضلة شفافة بين الجدول والتكلفة والمخاطر التقنية وأولويات المعنيين.', rationale_distractors_ar='{"A":"تتجاهل حماية الجدول وحدها آثار التكلفة والجدوى.","B":"تتجاهل حماية الميزانية وحدها التعرض التقني واللاحق.","C":"يحوّل الانتظار توقعاً قابلاً للإدارة إلى استجابة أكثر تقييداً."}'::jsonb where eco_task='Process-13';
update public.diagnostic_items set stem_ar='سلّم برنامج هجين سير عمل جديداً ومواد تدريب، لكن تحقق المنافع لا يزال دون المتوقع. تكمل فرق التشغيل التدريب ثم تعود إلى سير العمل القديم. يسرد ملف الانتقال مواعيد التسليم وإكمال التدريب، لكنه لا يتضمن ملاكاً تشغيليين أو مقاييس تبنٍ أو إجراءات تعزيز. أي قصور في الأداة يفسر الفجوة على نحو أفضل؟', options_ar='[{"id":"A","text":"لا يكرر سجل المخاطر معالم التسليم التقنية الواردة في الخطة المتكاملة."},{"id":"B","text":"لا تحدد خطة المشتريات مورّد تدريب بديلاً للدورات المكتملة."},{"id":"C","text":"تفتقر خطة الانتقال والمنافع إلى ملاك مسؤولين عن التبني، ومقاييس للنتائج، وإجراءات تعزيز."},{"id":"D","text":"لا يصنف سجل القضايا الاستخدام الطوعي لسير العمل السابق بوصفه عيباً تقنياً."}]'::jsonb, rationale_correct_ar='تربط الملكية التشغيلية ومقاييس التبني القابلة للملاحظة والتعزيز القدرة المسلّمة بالتغيير المؤسسي المتحقق.', rationale_distractors_ar='{"A":"لا ينشئ تكرار المعالم مساءلة عن التبني.","B":"لا يرتبط مورّد بديل بالسلوك الملحوظ بعد التدريب.","D":"استمرار الاستخدام قضية تبنٍ وليس بالضرورة عيباً برمجياً."}'::jsonb where eco_task='Business-6';
update public.diagnostic_items set stem_ar='لا يزال مشروع ضمن محفظة قابلاً للتنفيذ تقنياً، لكن أدلة سوق موثقة تظهر أن منتجه لن يحقق الحد الأدنى للمنفعة الاستراتيجية. ستستهلك المواصلة قدرة نادرة تحتاجها مبادرة أعلى قيمة، وتكلفة الإنهاء أقل من الإنفاق المتبقي المتوقع. يستشهد الراعي بالاستثمار السابق سبباً للمواصلة. بماذا ينبغي لمدير المشروع أن يوصي؟', options_ar='[{"id":"A","text":"المواصلة لأن التوقف سيمنع استرداد الاستثمار المنفق."},{"id":"B","text":"التوصية بالإنهاء عبر حوكمة المحفظة وتوثيق أدلة القيمة والقدرة والخروج الحالية."},{"id":"C","text":"خفض أهداف الجودة حتى يصبح توقع المنفعة الأصلي مجدياً مالياً."},{"id":"D","text":"إكمال المنتج قبل الإفصاح عن أدلة السوق لصناع قرار المحفظة."}]'::jsonb, rationale_correct_ar='ينبغي أن تحكم القيمة الحالية والمستقبلية قرار الاستمرار؛ فالإنفاق الغارق ليس سبباً لاستهلاك قدرة مقيدة إضافية.', rationale_distractors_ar='{"A":"الإنفاق السابق غير قابل للاسترداد ولا يثبت قيمة مستقبلية.","C":"لا يعيد خفض الجودة المنفعة الاستراتيجية التي دحضتها الأدلة.","D":"يقوض حجب الأدلة الجوهرية حوكمة المحفظة."}'::jsonb where eco_task='Business-7';
update public.diagnostic_items set stem_ar='تفضّل أدلة السوق الآن تكوين خدمة أصغر يمكن أن يصل إلى العملاء خلال ستة أسابيع، ويتوقع أن يحقق 80% من المنفعة الأصلية مقابل 45% من التكلفة المتبقية. لا يزال التكوين الأكبر ممكناً، لكنه سيصل بعد إطلاق منافس ويستهلك اختصاصيين محدودين. تسمح الحوكمة بتكييف النطاق عند تغير دراسة الجدوى. بأي خيار ينبغي لمدير المشروع أن يوصي؟', options_ar='[{"id":"A","text":"إكمال التكوين الأكبر لأنه يحافظ على عدد الميزات المعتمد أولاً."},{"id":"B","text":"تأجيل القرار حتى يؤكد إطلاق المنافس أثر السوق المتوقع."},{"id":"C","text":"تسليم التكوينين بالتتابع من دون تغيير تخصيص القدرة المعتمد."},{"id":"D","text":"التوصية بالتكوين الأصغر عبر ضبط التغيير باستخدام أدلة القيمة والتوقيت والتكلفة والقدرة المحدثة."}]'::jsonb, rationale_correct_ar='ينبغي لعملية التفصيل المخولة استخدام الأدلة الحالية لحماية القيمة بدلاً من الحفاظ على حجم المخرجات.', rationale_distractors_ar='{"A":"عدد الميزات ليس مقياس القيمة الحاكم.","B":"يهدر الانتظار ميزة حساسة للوقت رغم كفاية أدلة القرار.","C":"يتجاوز المقترح القدرة المحددة ويتجنب المفاضلة المطلوبة."}'::jsonb where eco_task='Business-8';
update public.diagnostic_items set stem_ar='سيُطلق مشروع حكومي في منطقتين تختلف فيهما متطلبات الاحتفاظ بالبيانات. يستوفي التصميم المعتمد القاعدة الأشد، لكن التشغيل يقترح تنويعاً إقليمياً أقل تكلفة قد يظل ممتثلاً. لم يكتمل التفسير القانوني، واتصالات الإطلاق مجدولة. ما الإجراء التالي قبل اعتماد التنويع؟', options_ar='[{"id":"A","text":"تأكيد الالتزامات المنطبقة وتقييم آثار الامتثال والقيمة والتشغيل."},{"id":"B","text":"اعتماد التنويع الأرخص لأن التصميم الأشد متاح بديلاً احتياطياً."},{"id":"C","text":"استخدام تصميم واحد في المنطقتين لأن التوحيد يزيل كل مخاوف الامتثال ذات الصلة."},{"id":"D","text":"تأجيل اتصالات الإطلاق إلى أن تنشر الجهات التنظيمية إرشادات تنفيذ إضافية."}]'::jsonb, rationale_correct_ar='يجب إثبات الالتزام المنطبق والآثار المتكاملة قبل اعتماد قرار تصميم خاص بالمنطقة.', rationale_distractors_ar='{"B":"لا تثبت وفورات التكلفة الامتثال أو قبول التعرض التشغيلي.","C":"قد يقلل التوحيد التعقيد لكنه لا يحسم التفسير القانوني تلقائياً.","D":"تأجيل الاتصالات بالكامل سابق لأوانه قبل أن يحدد التحليل القيد الحقيقي."}'::jsonb where eco_task='Business-3';
update public.diagnostic_items set stem_ar='لدى برنامج هجين فرق ناجحة تقنياً، لكنها تفسر بصورة مختلفة النتيجة الجماعية المستهدفة. بدأت الأولويات المحلية تتنافس، ويطلب القادة جداول أكثر تفصيلاً. ما الذي ينبغي لمدير البرنامج تيسيره أولاً لاستعادة اتساق القرارات؟', options_ar='[{"id":"A","text":"إنشاء بيان مشترك للنتيجة مع المعنيين وربط أهداف الفرق ومقاييسها به."},{"id":"B","text":"نشر جدول تفصيلي واحد لكل فريق ذي صلة بصرف النظر عن نهج التسليم."},{"id":"C","text":"السماح لكل فريق بتعريف النجاح مستقلاً حتى مرحلة التكامل."},{"id":"D","text":"تصعيد كل تعارض في الأولويات إلى اللجنة التوجيهية."}]'::jsonb, rationale_correct_ar='توفر الرؤية المشتركة والمحدثة إطار القرار اللازم قبل زيادة تفاصيل الخطط.', rationale_distractors_ar='{"B":"لا تحل تفاصيل الجدول تفسيرات النجاح المتعارضة.","C":"تؤجل التعريفات المستقلة تعارض التكامل وتضخمه.","D":"تقع المواءمة الروتينية ضمن مسؤولية البرنامج قبل تصعيد الحوكمة."}'::jsonb where eco_task='Reserve-01';
update public.diagnostic_items set stem_ar='يعتمد فريق رشيق على معماري واحد سيغادر بعد التكرار التالي. التوثيق غير مكتمل، ويتجنب الأعضاء الآخرون قرارات المعمارية خشية الخطأ. يمكن استمرار التسليم لفترة وجيزة. ما الإجراء الأنسب لدعم نقل معرفة مستدام؟', options_ar='[{"id":"A","text":"مطالبة المعماري بتوثيق كل شيء منفرداً في الأسبوع الأخير."},{"id":"B","text":"إقران أعضاء الفريق بالمعماري في قرارات فعلية وتوثيق المعرفة المتحقق منها أثناء العمل."},{"id":"C","text":"تأجيل قرارات المعمارية ذات الصلة حتى تعيين بديل."},{"id":"D","text":"نقل الملكية إلى أقدم مطور من دون إعداد."}]'::jsonb, rationale_correct_ar='ينقل العمل الثنائي المعرفة الضمنية والصريحة ويثبت الكفاءة في سياقها.', rationale_distractors_ar='{"A":"نادراً ما يوثق المستند وحده منطق القرار أو يبني القدرة.","C":"يزيد التأجيل الاعتماد وقد يقطع التسليم.","D":"لا تستبدل الأقدمية النقل المتعمد للمعرفة."}'::jsonb where eco_task='Reserve-02';
update public.diagnostic_items set stem_ar='يجب على مشروع تنبؤي تقديم تقرير شهري للجهات التنظيمية، وأسبوعي للراعي، واستثناءات تشغيلية يومية لفريق رقابة. يشكو المعنيين من تكرار التقارير وفقدان معلومات حرجة. ما الإجراء التالي عند تحديد نهج التواصل؟', options_ar='[{"id":"A","text":"إرسال التقرير التفصيلي نفسه إلى كل صاحب مصلحة ذي صلة."},{"id":"B","text":"إيقاف التقرير اليومي لأن التقرير الشهري إلزامي."},{"id":"C","text":"تحديد احتياجات كل جمهور من المعلومات والتوقيت والصيغة والملكية والتغذية الراجعة."},{"id":"D","text":"مطالبة المعنيين باسترجاع بيانات المشروع الخام عند الحاجة."}]'::jsonb, rationale_correct_ar='تمنع متطلبات المعلومات والتغذية الراجعة الخاصة بالجمهور الازدواجية مع الحفاظ على احتياجات الحوكمة.', rationale_distractors_ar='{"A":"لا تناسب التفاصيل المتطابقة قرارات ودوريات مختلفة.","B":"لا يحل التقرير الشهري الإلزامي محل معالجة الاستثناءات التشغيلية.","D":"ينقل الوصول إلى البيانات الخام مخاطر التفسير وقد لا يفي بالتزامات التقرير."}'::jsonb where eco_task='Reserve-03';
update public.diagnostic_items set stem_ar='يتوقع راعي منتج رشيق إدراج كل ميزة مطلوبة في الإصدار، بينما يعطي المستخدمون الأولوية للموثوقية ويحدد الفريق قيوداً في القدرة. تاريخ الإصدار ثابت. ما الإجراء الأنسب لمواءمة التوقعات من دون الوعد بنتيجة غير ممكنة؟', options_ar='[{"id":"A","text":"الالتزام بطلبات الراعي ذات الصلة ومطالبة الفريق بتحسين السرعة."},{"id":"B","text":"ترك المستخدمين يقررون وحدهم لأنهم يشغلون المنتج."},{"id":"C","text":"نقل تاريخ الإصدار من دون التشاور مع الحوكمة."},{"id":"D","text":"تيسير مفاضلات شفافة باستخدام القدرة والقيمة والموثوقية وقيود الإصدار."}]'::jsonb, rationale_correct_ar='تنشئ المفاضلات القائمة على الأدلة توقعاً مشتركاً قابلاً للتحقيق بين الاحتياجات المتنافسة.', rationale_distractors_ar='{"A":"يخفي الالتزام غير المدعوم قيد القدرة.","B":"المستخدمون مهمون لكنهم لا يملكون وحدهم قرارات الاستثمار والإصدار.","C":"يتجاوز تغيير التاريخ منفرداً سلطة المعنيين والحوكمة."}'::jsonb where eco_task='Reserve-04';

update public.diagnostic_items set stem_ar='أضاف مشروع تنبؤي مجموعة مجتمعية بوصفها صاحب مصلحة بعد بدء العمل في الموقع. لدى المجموعة مخاوف مشروعة، لكنها تتلقى تقارير تقنية لا تستطيع تفسيرها وتزداد شكوكها. ما الإجراء التالي لتحسين الإشراك؟', options_ar='[{"id":"A","text":"تفصيل التواصل وفق مخاوف المجموعة ومستوى فهمها، وإنشاء حوار، وتحديث خطة الإشراك."},{"id":"B","text":"مواصلة صيغة التقرير التقني المعتمدة لضمان الاتساق."},{"id":"C","text":"مطالبة الراعي بالتحدث نيابة عن المجموعة المجتمعية."},{"id":"D","text":"تقييد الإشراك حتى تقدم المجموعة اعتراضات رسمية."}]'::jsonb, rationale_correct_ar='يبني التواصل المتبادل الملائم الفهم ويدمج المعني المكتشف حديثاً.', rationale_distractors_ar='{"B":"لا يفيد الاتساق عندما يعجز الجمهور عن استخدام المعلومات.","C":"لا يستطيع الراعي استبدال التواصل المباشر مع المتأثرين.","D":"يحوّل الانتظار المخاوف القابلة للإدارة إلى مقاومة يمكن تجنبها."}'::jsonb where eco_task='Reserve-05';
update public.diagnostic_items set stem_ar='يحتاج مشروع تنبؤي إلى منشأة اختبار نادرة تتشاركها برامج أعلى أولوية. يفترض الخط المرجعي إتاحة متواصلة، لكن مكتب المحفظة يؤكد إتاحة جزئية فقط. تعتمد أنشطة حرجة عدة على المنشأة. أي إجراءين يشكلان معاً أقوى أساس لخطة موارد قابلة للتنفيذ؟ اختر إجابتين.', options_ar='[{"id":"A","text":"نمذجة الطلب على المنشأة مقابل النوافذ الزمنية المتاحة وتبعيات الجدول المتأثرة."},{"id":"B","text":"التفاوض على الإتاحة وتقييم البدائل المؤهلة باستخدام تحليل الأثر المتكامل."},{"id":"C","text":"الإبقاء على تواريخ الخط المرجعي وتصنيف النقص المؤكد بوصفه قضية للمراقبة."},{"id":"D","text":"اعتماد منشأة بديلة قبل مقارنة التكلفة والمدة اللازمة والملاءمة التقنية."}]'::jsonb, rationale_correct_ar='ينشئ تحليل الطلب والتفاوض على الإتاحة أو البدائل معاً خطة موارد قابلة للتنفيذ.', rationale_distractors_ar='{"C":"يُبقي تسجيل القيد من دون إعادة التخطيط الخط المرجعي غير قابل للتنفيذ.","D":"يتطلب الاستحواذ الكبير تحليلاً مقارناً وسلطة مناسبة."}'::jsonb where eco_task='Reserve-06';
update public.diagnostic_items set stem_ar='يلتزم مورّد مشروع هجين بمواعيد التسليم، لكنه يقدم مراراً أدلة أمنية ناقصة لازمة للقبول. تعوض الفرق ذلك يدوياً، وتظل العلاقة تعاونية. يقترب اعتماد الدفع والمتطلب صريح تعاقدياً. ما الإجراء التالي الأنسب بموجب اتفاق الشراء؟', options_ar='[{"id":"A","text":"قبول المخرجات ذات الصلة لأن مواعيد التشغيل تحققت."},{"id":"B","text":"إنهاء الاتفاق قبل استكمال تحليل أثر النقص المتكرر."},{"id":"C","text":"توثيق الأداء، وإنفاذ متطلب الأدلة، والاتفاق على خطة تصحيح محددة زمنياً."},{"id":"D","text":"حذف متطلب الأدلة الأمنية من القبولات المستقبلية."}]'::jsonb, rationale_correct_ar='تحمي إدارة الأداء التعاقدية والإجراء التصحيحي القبول مع الحفاظ على علاقة قابلة للتعافي.', rationale_distractors_ar='{"A":"لا يعفي أداء الجدول من التزامات القبول الأمني.","B":"قد يكون الإنهاء الفوري غير متناسب قبل تطبيق المعالجات التعاقدية.","D":"ينشئ حذف متطلب صحيح تعرضاً للامتثال."}'::jsonb where eco_task='Reserve-07';
update public.diagnostic_items set stem_ar='يوضح المخطط التعرض المتوقع للعملة في مشروع تنبؤي مع تأخر تواريخ الشراء تدريجياً. الاحتياطي المتاح 85 ألفاً، وحد التصعيد في الحوكمة 100 ألف. تظل خطة الشراء الحالية ضمن الحد، لكن التأخير يغير نمط التعرض. أي استجابة تحمي قيمة المشروع والامتثال للحوكمة على نحو أفضل؟', options_ar='[{"id":"A","text":"نمذجة بدائل التوقيت والتحوط، وتحديث التوقع، وعرض الاستجابة المدعومة عند الحد المنطبق."},{"id":"B","text":"استخدام رصيد الاحتياطي الحالي دليلاً على عدم الحاجة إلى مراقبة تواريخ الشراء."},{"id":"C","text":"نقل مشتريات مختارة إلى الشهر الأول من دون فحص قيود الإمداد أو التدفق النقدي أو الاعتماد."},{"id":"D","text":"تصعيد التعرض الحالي بوصفه تجاوزاً للحد رغم أن المخطط يضعه دون 100 ألف."}]'::jsonb, rationale_correct_ar='يتطلب الاتجاه تقييم خيارات الاستجابة والحوكمة في الوقت المناسب بدلاً من تجاهل التعرض أو تصنيفه خطأ.', rationale_distractors_ar='{"B":"لا يلغي الهامش الحالي التعرض المتزايد.","C":"قد ينشئ رد قائم على التاريخ وحده مشكلات إمداد وتمويل.","D":"لم تتجاوز القيمة الحالية حد التصعيد المحدد."}'::jsonb, visual_spec_ar='{"kind":"bar_chart","title":"التعرض المتوقع للعملة حسب شهر الشراء","labels":["الخطة الحالية","الشهر 1","الشهر 2","الشهر 3"],"values":[72,79,91,108],"unit":"ألف"}'::jsonb where eco_task='Reserve-08';
update public.diagnostic_items set stem_ar='تنجح الاختبارات الآلية لفريق رشيق، لكن العملاء يبلغون عن إخفاقات متقطعة تحت أنماط عبء العمل الفعلية. يقترح الفريق إضافة ميزات، بينما تطلب العمليات الاستقرار. تؤثر الإخفاقات في رحلة عميل مهمة ويمكن إعادة إنتاجها من بيانات الدعم. ما الذي ينبغي تشجيعه أولاً لتحسين الجودة؟', options_ar='[{"id":"A","text":"إعادة إنتاج ظروف عبء العمل، وتحديد فجوة الجودة، وتكييف ممارسات القبول والاختبار."},{"id":"B","text":"مواصلة تسليم الميزات لأن الاختبارات الآلية تحدد القبول."},{"id":"C","text":"مطالبة العمليات بمعالجة الإخفاقات بعد كل إصدار."},{"id":"D","text":"إيقاف التطوير ذي الصلة مدة مفتوحة حتى يستحيل وقوع أي عيب."}]'::jsonb, rationale_correct_ar='ينبغي لأدلة الاستخدام الفعلي تحديث متطلبات الجودة وضوابط الوقاية.', rationale_distractors_ar='{"B":"قد تغفل الاختبارات الحالية الظروف المهمة للعملاء.","C":"لا يصحح الإصلاح التشغيلي فجوة جودة التطوير.","D":"اليقين بانعدام العيوب غير واقعي والإيقاف المفتوح غير متناسب."}'::jsonb where eco_task='Reserve-09';
update public.diagnostic_items set stem_ar='يمكن لمشروع تنبؤي استعادة معلم عبر تداخل التصميم والإنشاء، لكن ذلك قد يزيد إعادة العمل وتعقيد مراجعة السلامة. يطلب التنفيذيون التزاماً بالتعافي اليوم. ما الاستجابة الأنسب قبل تغيير الجدول؟', options_ar='[{"id":"A","text":"تداخل العمل ذي الصلة لأن المعلم مهم تعاقدياً."},{"id":"B","text":"رفض تعافي الجدول لأن التداخل ينشئ عادة مخاطر غير مقبولة."},{"id":"C","text":"تحليل التبعيات ومخاطر إعادة العمل والسلامة، ثم طلب اعتماد خيار تعافٍ مدعوم."},{"id":"D","text":"حذف مراجعات السلامة من المسار الحرج."}]'::jsonb, rationale_correct_ar='يتطلب ضغط الجدول جدوى ومخاطر وسلطة متكاملة، لا قراراً قائماً على التاريخ وحده.', rationale_distractors_ar='{"A":"لا تجعل الأهمية التداخل غير الآمن أو غير الممكن مقبولاً.","B":"قد يكون التداخل ممكناً عندما تدعمه المخاطر والتبعيات.","D":"لا يجوز إلغاء ضوابط السلامة لصنع تعافٍ ظاهري للجدول."}'::jsonb where eco_task='Reserve-10';
update public.diagnostic_items set stem_ar='يقترب مشروع هجين من التسليم النهائي. حضرت العمليات العروض لكنها لم تقبل ملكية الدعم، كما أن عدة ضمانات للمورّدين غير موثقة، ويريد الراعي إنهاء عمل الفريق هذا الأسبوع. ما الإجراء التالي قبل إغلاق المشروع؟', options_ar='[{"id":"A","text":"الإغلاق لأن حضور العروض يُعد قبولاً تشغيلياً."},{"id":"B","text":"التحقق مع المعنيين من معايير الانتقال والملكية والتوثيق والتزامات الإغلاق المتبقية."},{"id":"C","text":"إنهاء عمل الفريق ومطالبة العمليات بحل البنود الناقصة."},{"id":"D","text":"تمديد المشروع ستة أشهر ثابتة بصرف النظر عن العمل المتبقي."}]'::jsonb, rationale_correct_ar='يتبع الإغلاق تحقق الجاهزية للانتقال وإتمام الالتزامات، لا ضغط الجدول وحده.', rationale_distractors_ar='{"A":"لا تساوي المشاركة قبول الجاهزية أو الملكية رسمياً.","C":"ينقل إنهاء الفريق مبكراً مخاطر غير محلولة من دون اتفاق.","D":"لا يستند التمديد الاعتباطي إلى معايير الإغلاق."}'::jsonb where eco_task='Reserve-11';
update public.diagnostic_items set stem_ar='تُظهر أدلة العملاء أن ميزة رشيقة مخططة تحل مشكلة نادرة، بينما يفيد بديل أصغر معظم المستخدمين ويمكن إصداره أسرع. لا يزال صاحب مصلحة رفيع يفضل الميزة الأصلية. ما الذي ينبغي لمدير المشروع تشجيعه أولاً؟', options_ar='[{"id":"A","text":"تسليم الميزة الأصلية لأنها تحظى بدعم رفيع."},{"id":"B","text":"بناء الخيارين من دون تغيير قدرة التكرار."},{"id":"C","text":"تأجيل القرار حتى يتفق المستخدمون المعنيون."},{"id":"D","text":"مقارنة القيمة القابلة للقياس والتغذية الراجعة، ثم إعادة ترتيب الأولويات عبر عملية قرار المنتج."}]'::jsonb, rationale_correct_ar='ينبغي لأدلة القيمة الشفافة توجيه الأولويات عبر عملية المنتج المخولة.', rationale_distractors_ar='{"A":"لا يثبت النفوذ وحده قيمة للعميل.","B":"يتجنب تجاهل القدرة المفاضلة المطلوبة.","C":"الإجماع الشامل غير لازم ويؤخر التعلم."}'::jsonb where eco_task='Reserve-12';
update public.diagnostic_items set stem_ar='تلقى مشروع هجين تغيير تصميم معتمداً، لكن أحد فرق التسليم يستمر في استخدام المواصفة السابقة لأن مستودعه المحلي لم يُحدث. بدأت فرق أخرى إعادة العمل. ما أول إجراء لضبط التغيير المعتمد؟', options_ar='[{"id":"A","text":"عكس التغيير المعتمد ليتوافق مع المستودع القديم."},{"id":"B","text":"لوم الفريق على عدم متابعة سجلات الحوكمة."},{"id":"C","text":"إيقاف العمل المتأثر، ومزامنة الخط المرجعي والاتصالات المعتمدة، وتقييم آثار إعادة العمل."},{"id":"D","text":"السماح بالمواصفتين حتى اجتماع الحوكمة التالي."}]'::jsonb, rationale_correct_ar='تنفذ المزامنة الفورية وتقييم الأثر التغيير المخول وتحدان من إعادة العمل.', rationale_distractors_ar='{"A":"لا يبطل إخفاق التواصل القرار المخول.","B":"لا يوقف اللوم العمل الخاطئ ولا يصلح ضبط التهيئة.","D":"تزيد المواصفات المتوازية عدم الاتساق وإعادة العمل."}'::jsonb where eco_task='Reserve-13';
update public.diagnostic_items set stem_ar='يعوق فريقاً رشيقاً طابور مراجعة أمنية مملوك خارج المشروع. لم تغير الطلبات غير الرسمية المتكررة الأولوية، وأصبح إصدار ذو قيمة كبيرة للعميل معرضاً للخطر. ما الإجراء التالي الأنسب؟', options_ar='[{"id":"A","text":"الإصدار من دون مراجعة أمنية لأن قيمة العميل كبيرة."},{"id":"B","text":"تكميم الأثر واستخدام مسار التصعيد المحدد مع التعاون على خيار مراجعة قابل للتنفيذ."},{"id":"C","text":"مطالبة الفريق بالانتظار من دون تحديث المعنيين."},{"id":"D","text":"وضع علامة اكتمال على العمل المعوق لحماية السرعة."}]'::jsonb, rationale_correct_ar='يطبق التصعيد القائم على الأدلة والتعاون تدخلاً من دون تجاوز الرقابة المطلوبة.', rationale_distractors_ar='{"A":"لا تجيز القيمة تجاوز الالتزامات الأمنية.","C":"يترك الانتظار السلبي العائق بلا إدارة.","D":"يخفي التقرير الخاطئ للتقدم العائق ولا يزيله."}'::jsonb where eco_task='Reserve-14';
update public.diagnostic_items set stem_ar='يعتمد مشروع تنبؤي على مكوّن وحيد المصدر من منطقة تواجه قيوداً تجارية متصاعدة. لا يزال التسليم وفق الجدول، لكن تأهيل بديل يستغرق أشهراً والشحنة التالية غير مؤكدة. أي إجراءين يحافظان على خيارات القرار بصورة أفضل بينما لا يزال التهديد ناشئاً؟ اختر إجابتين.', options_ar='[{"id":"A","text":"تحديد التعرض والمحفزات وسيناريوهات مدة التأهيل في تحليل المخاطر."},{"id":"B","text":"تطوير خيارات الاستجابة مع المشتريات وإبلاغ حدود القرار عبر الحوكمة."},{"id":"C","text":"تأجيل الإجراء حتى تفوت شحنة موعدها التعاقدي وتصبح قضية مؤكدة."},{"id":"D","text":"إلغاء المورّد الآن قبل تقييم جدوى البديل أو التعرض أثناء الانتقال."}]'::jsonb, rationale_correct_ar='يحافظ تحليل التعرض المبكر وتخطيط الاستجابة المحكوم على الخيارات قبل تحول التهديد إلى قضية.', rationale_distractors_ar='{"C":"يهدر الانتظار المدة النادرة اللازمة للتأهيل.","D":"قد ينشئ الإلغاء غير المدروس الاضطراب المراد تجنبه."}'::jsonb where eco_task='Reserve-15';
update public.diagnostic_items set stem_ar='تجري مؤسسة هجينة اجتماعات استعادية، لكن عيب التسليم نفسه يتكرر عبر المشاريع لأن الدروس تبقى في ملفات الفرق المنفردة. تريد القيادة التحسين من دون إضافة فعالية تقارير جديدة. تراجع الحوكمة الحالية بالفعل الامتثال للأصول المشتركة للعملية. ما الإجراء التالي لمجتمع مديري المشاريع؟', options_ar='[{"id":"A","text":"مطالبة كل فريق بإجراء اجتماعات استعادية أطول."},{"id":"B","text":"أرشفة الدروس ذات الصلة عند إغلاق المشروع لأغراض التدقيق."},{"id":"C","text":"تعيين مسؤولية تحديث أصل العملية المشترك والتحقق من التبني عبر المراجعات الحالية."},{"id":"D","text":"إنشاء اجتماع أسبوعي جديد لكل موظف ذي صلة بالمشروع."}]'::jsonb, rationale_correct_ar='يحوّل تضمين تحسين مملوك في أصول العملية المشتركة والمراجعات الحالية الدروس إلى تغيير مؤسسي.', rationale_distractors_ar='{"A":"لا يضمن مزيد من النقاش التبني عبر المشاريع.","B":"لا تحسن الأرشفة من دون دمج الممارسة.","D":"تضيف فعالية عامة جديدة تكلفة من دون استهداف آلية التبني."}'::jsonb where eco_task='Reserve-16';

do $$
declare missing_count integer;
begin
  select count(*) into missing_count from public.diagnostic_items
  where track_id='pmbok8' and status='live' and (
    nullif(btrim(stem_ar),'') is null or options_ar is null
    or nullif(btrim(rationale_correct_ar),'') is null or rationale_distractors_ar is null
    or jsonb_array_length(options_ar) <> jsonb_array_length(options)
    or (select array_agg(x->>'id' order by x->>'id') from jsonb_array_elements(options_ar) x)
       <> (select array_agg(x->>'id' order by x->>'id') from jsonb_array_elements(options) x)
  );
  if missing_count <> 0 then raise exception 'Arabic localization incomplete for % live PMBOK8 items', missing_count; end if;
end $$;

notify pgrst, 'reload schema';
